const content=document.querySelector('#content'),title=document.querySelector('#title');let mapClockTimer=null,pendingMapName='',pendingQuestId='',pendingObjectiveId='',appLanguage='pt-BR';const t=key=>window.tarkasI18n?.t(appLanguage,key)||key;function stopMapClock(){if(mapClockTimer){clearInterval(mapClockTimer);mapClockTimer=null}}
function bossRadarHtml(bosses){if(!bosses?.length)return'<section class="boss-radar"><label>Boss Radar <b>0</b></label><small>Nenhum boss estruturado para este mapa no cache local.</small></section>';const percent=value=>Math.round((Number(value)||0)*100)+'%';return'<section class="boss-radar"><label>Boss Radar <b>'+bosses.length+'</b></label><div class="boss-radar-list">'+bosses.map(b=>'<article class="boss-radar-card"><strong>'+b.name+'</strong><span class="boss-chance">'+percent(b.chance)+'</span><small>'+((b.locations||[]).map(l=>l.name+' '+percent(l.chance)).join(' · ')||'Sem posição estruturada')+'</small>'+((b.escorts||[]).length?'<em>Grupo: '+b.escorts.map(e=>e.name+(e.amount?' ×'+e.amount:'')).join(' · ')+'</em>':'')+(b.spawnTime>=0?'<em>Entrada: '+Math.floor(b.spawnTime/60)+' min'+(b.spawnTimeRandom?' (variável)':'')+'</em>':'')+'</article>').join('')+'</div></section>'}
const names={dashboard:'Visão Geral',quests:'Quests',mapa:'Mapa Interativo',battlepass:'Battle Pass',hideout:'Hideout',market:'Itens e Mercado'};
function syncLanguageChrome(){
  document.documentElement.lang=appLanguage;
  const select=document.querySelector('#language-select');if(select)select.value=appLanguage;
  const labels={dashboard:'dashboard',quests:'quests',mapa:'mapa',battlepass:'battlepass',hideout:'hideout',armory:'armory',operations:'operations',roadmap:'roadmap',story:'story',market:'market'};
  Object.entries(labels).forEach(([page,key])=>{names[page]=t(key);const button=document.querySelector('#nav button[data-page="'+page+'"]');if(button){const icon=button.dataset.icon||(button.textContent.match(/^[^\w]*\s*/)?.[0]||'');button.dataset.icon=icon;button.textContent=icon+names[page]}});
  document.querySelector('#project-label').textContent=t('project');document.querySelector('#language-label').textContent=t('languageLabel');document.querySelector('#local-data-label').textContent=t('localData');document.querySelector('#developed-by').textContent=t('developedBy');
  const brandVersion=document.querySelector('#brand-version');if(brandVersion&&brandVersion.textContent.includes('carregando'))brandVersion.textContent=t('commandCenter')+' · '+t('loadingVersion');
  const installed=document.querySelector('#installed-version');if(installed&&installed.textContent.includes('carregando'))installed.textContent='Tarkas · '+t('loadingVersion');
  title.textContent=names[document.querySelector('#nav button.active')?.dataset.page||'dashboard'];
  if(typeof window.tarkasQuickNavReady==='function'){window.tarkasQuickNavReady()}
}
function markerGlyph(type,cx,cy,r){const s=Math.max(r,1.5),x=Number(cx),y=Number(cy);if(type==='extract')return`<rect class="marker-shape" x="${x-s}" y="${y-s}" width="${2*s}" height="${2*s}" rx="${s*.25}"/><path class="marker-glyph" d="M ${x-s*.45} ${y} H ${x+s*.55} M ${x+s*.12} ${y-s*.42} L ${x+s*.55} ${y} L ${x+s*.12} ${y+s*.42}"/>`;if(type==='spawn')return`<path class="marker-shape" d="M ${x} ${y-s*1.2} L ${x+s*1.1} ${y+s} L ${x-s*1.1} ${y+s} Z"/><circle class="marker-glyph-dot" cx="${x}" cy="${y+s*.22}" r="${s*.22}"/>`;if(type==='boss')return`<path class="marker-shape boss-silhouette" d="M ${x-s*.72} ${y+s} Q ${x-s*.72} ${y+s*.1} ${x-s*.35} ${y-s*.1} Q ${x-s*.58} ${y-s*.95} ${x} ${y-s*.95} Q ${x+s*.58} ${y-s*.95} ${x+s*.35} ${y-s*.1} Q ${x+s*.72} ${y+s*.1} ${x+s*.72} ${y+s} Z"/><circle class="marker-glyph-dot" cx="${x}" cy="${y-s*.38}" r="${s*.23}"/>`;if(type==='switch')return`<rect class="marker-shape" x="${x-s*.72}" y="${y-s*.72}" width="${s*1.44}" height="${s*1.44}" transform="rotate(45 ${x} ${y})"/><path class="marker-glyph" d="M ${x} ${y-s*.52} V ${y+s*.52} M ${x-s*.35} ${y-s*.1} L ${x} ${y-s*.52} L ${x+s*.35} ${y-s*.1}"/>`;return`<circle class="marker-shape" cx="${x}" cy="${y}" r="${s}"/><path class="marker-glyph" d="M ${x} ${y-s*.58} V ${y+s*.58} M ${x-s*.58} ${y} H ${x+s*.58}"/>`}
function decorateMapMarkers(){document.querySelectorAll('.overlaymap .mark:not([data-symbol])').forEach(mark=>{const circle=mark.querySelector(':scope>circle'),type=[...mark.classList].find(c=>['extract','spawn','boss','objective','switch'].includes(c));if(!circle||!type)return;mark.insertAdjacentHTML('afterbegin',markerGlyph(type,circle.getAttribute('cx'),circle.getAttribute('cy'),circle.getAttribute('r')));circle.remove();mark.dataset.symbol=type})}
function bindMapMarkerDetails(){document.querySelectorAll('.overlaymap .mark:not([data-details-bound])').forEach(mark=>{const type=[...mark.classList].find(c=>['extract','spawn','boss','objective','switch'].includes(c));if(!type)return;const open=event=>{event.preventDefault();event.stopPropagation();const stage=mark.closest('#mapstage'),name=mark.querySelector('title')?.textContent||'Marcador sem descrição',labels={extract:'Extração',spawn:'Spawn',boss:'Boss',objective:'Objetivo de quest',switch:'Interruptor'},notes={extract:'Ponto de extração indicado pelos dados locais.',spawn:'Área de surgimento indicada pelos dados locais.',boss:'Local e chance apresentados conforme os dados estruturados disponíveis.',objective:'Objetivo relacionado ao seu plano de raid.',switch:'Interruptor mapeado nos dados estruturados disponíveis.'};stage?.querySelector('#marker-details')?.remove();if(!stage)return;const panel=document.createElement('section');panel.id='marker-details';panel.className='marker-details';const close=document.createElement('button');close.type='button';close.className='marker-details-close';close.textContent='Fechar';close.onclick=()=>panel.remove();const kind=document.createElement('span');kind.className='tag';kind.textContent=labels[type];const heading=document.createElement('h3');heading.textContent=name;const note=document.createElement('p');note.textContent=notes[type];panel.append(kind,heading,note,close);stage.append(panel)};mark.addEventListener('pointerdown',event=>event.stopPropagation());mark.addEventListener('click',open);mark.dataset.detailsBound='true'})}
const markerDetailsObserver=new MutationObserver(()=>bindMapMarkerDetails());markerDetailsObserver.observe(content,{childList:true,subtree:true});
const markerSymbolObserver=new MutationObserver(()=>decorateMapMarkers());markerSymbolObserver.observe(content,{childList:true,subtree:true});
async function addFocusedQuestGuide(){const stage=document.querySelector('#mapstage'),banner=stage?.querySelector('.focusbanner');if(!stage||!banner||stage.querySelector('.map-quest-guide')||stage.dataset.questGuideLoading)return;stage.dataset.questGuideLoading='true';try{const questName=banner.textContent.replace(/^Quest em foco:\s*/,'').split(' · ')[0].trim(),catalog=await window.tarkas.questCatalog('regular'),quest=catalog.quests.find(entry=>entry.name===questName);if(!quest)return;const guide=document.createElement('section');guide.className='map-quest-guide';const intro=document.createElement('header');intro.innerHTML='<small>GUIA PASSO A PASSO</small><h3></h3><p>Faça os passos nesta ordem. Os marcadores de objetivo no mapa mostram os locais disponíveis na base.</p>';intro.querySelector('h3').textContent=quest.name;const steps=document.createElement('ol');quest.objectives.forEach((objective,index)=>{const item=document.createElement('li'),number=document.createElement('b'),copy=document.createElement('div'),title=document.createElement('strong'),note=document.createElement('small');number.textContent=String(index+1);title.textContent=objective.description+(objective.count>1?' ×'+objective.count:'');const details=[];if(objective.items?.length)details.push('Leve/obtenha: '+objective.items.map(entry=>entry.name).join(', '));if(objective.foundInRaid)details.push('Item deve ser encontrado em raid');if(objective.maps?.length)details.push('Mapa: '+objective.maps.join(', '));if(objective.optional)details.push('Etapa opcional');note.textContent=details.join(' · ')||'Confira os marcadores dourados e a descrição do objetivo.';copy.append(title,note);item.append(number,copy);steps.append(item)});guide.append(intro,steps);banner.insertAdjacentElement('afterend',guide)}catch{}finally{delete stage.dataset.questGuideLoading}}
const focusedQuestGuideObserver=new MutationObserver(addFocusedQuestGuide);focusedQuestGuideObserver.observe(content,{childList:true,subtree:true});
function highlightQuestDocuments(){const stage=document.querySelector('#mapstage');if(!stage)return;const terms=/\b(document|documents|dossi[eê]|arquivo|folder|intel|letter|carta|pap[eé]is|file|files)\b/i,docs=[...stage.querySelectorAll('.overlaymap .mark.objective')].filter(mark=>terms.test(mark.querySelector('title')?.textContent||''));docs.forEach(mark=>mark.classList.add('document'));const legend=stage.querySelector('.legend');if(legend&&docs.length&&!legend.querySelector('.document-legend')){const item=document.createElement('span');item.className='document-legend';item.textContent='Documento de quest';legend.append(item)}const head=stage.querySelector('.maphead');if(head&&docs.length&&!head.querySelector('.map-document-status')){const status=document.createElement('small');status.className='map-document-status';status.textContent=docs.length+' documento'+(docs.length>1?'s':'')+' marcado'+(docs.length>1?'s':'');head.append(status)}}
const documentMarkerObserver=new MutationObserver(highlightQuestDocuments);documentMarkerObserver.observe(content,{childList:true,subtree:true});

let pendingMapSpecialFilter='';
function classifySpecialMapMarkers(stage){
  if(!stage)return;
  const documentTerms=/\b(document|documents|dossi[eê]|arquivo|folder|intel|letter|carta|pap[eé]is|file|files)\b/i;
  const stashTerms=/\b(stash|cache|hidden cache|esconderijo|suprimentos escondidos)\b/i;
  stage.querySelectorAll('.overlaymap .mark.objective').forEach(mark=>{const label=mark.querySelector('title')?.textContent||'';mark.classList.toggle('document',documentTerms.test(label));mark.classList.toggle('stash',stashTerms.test(label))});
}
function applySpecialMapFilter(stage){
  if(!stage)return;
  classifySpecialMapMarkers(stage);
  const documents=stage.dataset.specialFilter==='documents',stashes=stage.dataset.specialFilter==='stashes';
  stage.querySelectorAll('.overlaymap .mark').forEach(mark=>{if((documents&&!mark.classList.contains('document'))||(stashes&&!mark.classList.contains('stash')))mark.classList.add('special-filter-hidden');else mark.classList.remove('special-filter-hidden')});
  const count=stage.querySelectorAll('.overlaymap .mark.'+(documents?'document':'stash')+':not(.out-of-bounds)').length;
  let notice=stage.querySelector('.map-special-filter-notice');
  if(!documents&&!stashes){stage.querySelectorAll('.document-map-label').forEach(node=>node.remove());delete stage.dataset.documentLabelSignature;notice?.remove();return}
  if(!notice){notice=document.createElement('div');notice.className='map-special-filter-notice';stage.querySelector('.maphead')?.insertAdjacentElement('afterend',notice)}
  notice.textContent=count?(documents?'Filtro: somente documentos com localização mapeada ('+count+').':'Filtro: somente stashes com localização mapeada ('+count+').'):(documents?'Nenhuma localização de documento verificada foi encontrada neste mapa nos dados locais.':'Nenhuma localização de stash verificada foi encontrada neste mapa nos dados locais.');
}
function installMapSpecialFilterControls(){
  const toolbar=document.querySelector('.toolbar:has(#raidmap)');if(!toolbar||toolbar.dataset.specialFilters)return;toolbar.dataset.specialFilters='ready';
  const documents=document.createElement('label'),stashes=document.createElement('label');
  documents.innerHTML='<input id="fdocuments" type="checkbox"> Documentos';stashes.innerHTML='<input id="fstashes" type="checkbox"> Stashes';toolbar.insertBefore(documents,toolbar.querySelector('#eftclock'));toolbar.insertBefore(stashes,toolbar.querySelector('#eftclock'));
  const choose=kind=>{const stage=document.querySelector('#mapstage');if(!stage)return;stage.dataset.specialFilter=kind;documents.querySelector('input').checked=kind==='documents';stashes.querySelector('input').checked=kind==='stashes';if(kind){['fx','fs','fb','fq','fw'].forEach(id=>{const input=document.querySelector('#'+id);if(input){input.checked=false;input.dispatchEvent(new Event('change'))}})}applySpecialMapFilter(stage)};
  documents.querySelector('input').onchange=event=>choose(event.target.checked?'documents':'');
  stashes.querySelector('input').onchange=event=>choose(event.target.checked?'stashes':'');
}
function applyPendingMapSpecialFilter(){
  const stage=document.querySelector('#mapstage');if(!stage?.querySelector('.overlaymap'))return;
  installMapSpecialFilterControls();
  if(pendingMapSpecialFilter){stage.dataset.specialFilter=pendingMapSpecialFilter;const input=document.querySelector(pendingMapSpecialFilter==='documents'?'#fdocuments':'#fstashes');if(input){input.checked=true;input.dispatchEvent(new Event('change'))}pendingMapSpecialFilter=''}
  applySpecialMapFilter(stage);
}
