function addMapKeyGuide(){const out=document.querySelector('#raidout'),summary=out?.querySelector('.raid-summary .raid-checklist');if(!out||!summary||out.querySelector('.map-key-guide'))return;const keys=[...summary.querySelectorAll('.raid-check-item')].map(row=>({image:row.querySelector('img')?.src||'',name:row.querySelector('span')?.childNodes[0]?.textContent?.trim()||'',quests:row.querySelector('em')?.textContent||''})).filter(key=>key.name);const panel=document.createElement('section');panel.className='map-key-guide';const heading=document.createElement('header');heading.innerHTML='<small>CHAVES E ACESSOS</small><h3>O que cada chave libera nesta rota</h3><p>Estas chaves são necessárias pelas quests em foco neste mapa. Clique em uma para ver a missão relacionada.</p>';panel.append(heading);const list=document.createElement('div');if(keys.length){keys.forEach(key=>{const button=document.createElement('button');button.type='button';button.innerHTML=(key.image?'<img src="'+key.image+'" alt="">':'')+'<span><b></b><small></small></span>';button.querySelector('b').textContent=key.name;button.querySelector('small').textContent='Usada em: '+key.quests;button.onclick=()=>{const target=[...document.querySelectorAll('#raidout .qrow')].find(row=>row.querySelector('h3')?.textContent===key.quests);target?.scrollIntoView({behavior:'smooth',block:'center'})};list.append(button)})}else list.innerHTML='<small>Nenhuma chave é exigida pelas quests em foco. O mapa não vai inventar portas ou posições sem uma fonte verificável.</small>';panel.append(list);out.querySelector('.raid-summary')?.insertAdjacentElement('beforebegin',panel)}
