const mapViewportObserver=new MutationObserver(()=>document.querySelectorAll('.mapcanvas:not([data-viewport])').forEach(canvas=>{const world=document.createElement('div');world.className='mapworld';while(canvas.firstChild)world.append(canvas.firstChild);const controls=document.createElement('div');controls.className='map-viewport-controls';controls.innerHTML='<button type="button" data-zoom-in aria-label="Aumentar mapa">+</button><button type="button" data-zoom-out aria-label="Diminuir mapa">−</button><button type="button" data-zoom-reset aria-label="Centralizar mapa"><span data-zoom-label>100%</span> centralizar</button>';canvas.append(world,controls);canvas.dataset.viewport='ready';enableMapViewport(canvas,controls)}));mapViewportObserver.observe(content,{childList:true,subtree:true});
