async function addQuestRewardCards(){const list=document.querySelector('#realquests');if(!list||list.dataset.rewardCards)return;list.dataset.rewardCards='loading';try{const catalog=await window.tarkas.questCatalog('regular');const byName=new Map(catalog.quests.map(quest=>[quest.name,quest]));list.querySelectorAll('.qrow').forEach(row=>{if(row.querySelector('.quest-rewards'))return;const quest=byName.get(row.querySelector('h3')?.textContent);if(!quest?.rewards?.length)return;const panel=document.createElement('section'),label=document.createElement('label'),items=document.createElement('div');panel.className='quest-rewards';label.textContent='RECOMPENSAS';quest.rewards.slice(0,8).forEach(reward=>{const entry=document.createElement('span');entry.className='quest-reward '+reward.kind;if(reward.icon){const image=document.createElement('img');image.src=reward.icon;image.alt='';entry.append(image)}entry.append(document.createTextNode(reward.label));items.append(entry)});panel.append(label,items);row.querySelector('small')?.insertAdjacentElement('afterend',panel)});list.dataset.rewardCards='ready'}catch{list.dataset.rewardCards='error'}}
const questRewardObserver=new MutationObserver(addQuestRewardCards);questRewardObserver.observe(content,{childList:true,subtree:true});
