function playRaidRoute(stage){
  if(!stage)return;
  stage.scrollIntoView({behavior:'smooth',block:'start'});
  const svg=stage.querySelector('.overlaymap'),point=mark=>{const circle=mark?.querySelector('circle,.marker-shape[cx]');if(circle)return{x:Number(circle.getAttribute('cx')),y:Number(circle.getAttribute('cy'))};const rect=mark?.querySelector('rect.marker-shape');if(rect)return{x:Number(rect.getAttribute('x'))+Number(rect.getAttribute('width'))/2,y:Number(rect.getAttribute('y'))+Number(rect.getAttribute('height'))/2};const path=mark?.querySelector('path.marker-shape')?.getAttribute('d')?.match(/M\s*([\d.-]+)\s+([\d.-]+)/);return path?{x:Number(path[1]),y:Number(path[2])}:null},distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),visible=selector=>[...stage.querySelectorAll(selector)].filter(mark=>!mark.classList.contains('out-of-bounds')&&point(mark));
  const special=stage.dataset.specialFilter==='documents'?'.mark.document':stage.dataset.specialFilter==='stashes'?'.mark.stash':'.mark.objective.focused,.mark.objective';
  const objectives=visible('.overlaymap '+special),spawns=visible('.overlaymap .mark.spawn'),extracts=visible('.overlaymap .mark.extract');
  const target=objectives.find(mark=>mark.classList.contains('focused'))||objectives[0];
  if(!svg||!target){const banner=stage.querySelector('.focusbanner');if(banner){banner.classList.remove('route-pulse');void banner.offsetWidth;banner.classList.add('route-pulse')}return}
  const targetPoint=point(target),start=spawns.sort((a,b)=>distance(point(a),targetPoint)-distance(point(b),targetPoint))[0],exit=extracts.sort((a,b)=>distance(point(a),targetPoint)-distance(point(b),targetPoint))[0],route=[start,target,exit].filter(Boolean),points=route.map(point).filter(Boolean);
  svg.querySelector('.tarkas-route-layer')?.remove();const layer=document.createElementNS('http://www.w3.org/2000/svg','g');layer.setAttribute('class','tarkas-route-layer');const line=document.createElementNS('http://www.w3.org/2000/svg','polyline');line.setAttribute('class','tarkas-route-line');line.setAttribute('points',points.map(p=>p.x+','+p.y).join(' '));layer.append(line);points.forEach((p,index)=>{const node=document.createElementNS('http://www.w3.org/2000/svg','circle');node.setAttribute('class','tarkas-route-node route-node-'+index);node.setAttribute('cx',p.x);node.setAttribute('cy',p.y);node.setAttribute('r',index===1?6:4);layer.append(node)});svg.append(layer);
  stage.querySelectorAll('.route-step').forEach(mark=>mark.classList.remove('route-step'));route.forEach((mark,index)=>setTimeout(()=>{mark.classList.add('route-step');setTimeout(()=>mark.classList.remove('route-step'),1700)},index*420));
  const map=stage.querySelector('.mapcanvas');map?.classList.add('route-active');setTimeout(()=>map?.classList.remove('route-active'),3100);
  let note=stage.querySelector('.map-route-note');if(!note){note=document.createElement('div');note.className='map-route-note';stage.querySelector('.legend')?.insertAdjacentElement('beforebegin',note)}note.textContent='Rota sugerida: '+(start?'spawn possível → ':'')+(stage.dataset.specialFilter==='documents'?'documento':'objetivo')+(exit?' → extração mais próxima':'')+'. Ajuste conforme seu spawn real e o perigo da raid.';
}

function addRaidBriefing(){
  const out=document.querySelector('#raidout');
  const stage=document.querySelector('#mapstage');
  const mapName=stage?.querySelector('.maphead b')?.textContent;
  if(!out||!mapName||out.querySelector('.raid-briefing'))return;
  const questCount=out.querySelector('.card .num')?.textContent||'0';
  const keyCount=out.querySelector('.raid-checklist label b')?.textContent||'0';
  const itemCount=out.querySelectorAll('.raid-checklist label b')[1]?.textContent||'0';
  const extractCount=(stage.querySelector('.maphead span')?.textContent.match(/(\d+) extrações/)||[])[1]||'0';
  const briefing=document.createElement('section');
  briefing.className='raid-briefing';
  briefing.innerHTML=`<div class="raid-briefing-title"><span>Plano de raid</span><b>${mapName}</b></div><div class="raid-briefing-stats"><span><b>${questCount}</b> quests</span><span><b>${keyCount}</b> chaves</span><span><b>${itemCount}</b> itens</span><span><b>${extractCount}</b> extrações</span></div><ol><li>Revise chaves e itens antes de entrar.</li><li>Ative <b>Objetivos</b> e procure os marcadores dourados.</li><li>Defina a saída usando as extrações no mapa.</li></ol><button type="button" class="raid-focus-map">Ver rota no mapa</button></section>`;
  out.prepend(briefing);
  briefing.querySelector('.raid-focus-map').onclick=()=>playRaidRoute(stage);
}
const raidBriefingObserver=new MutationObserver(addRaidBriefing);
raidBriefingObserver.observe(content,{childList:true,subtree:true});

const renderRaidScreen=raid;
raid=async function(){
  content.innerHTML='<div class="placeholder"><b>Abrindo mapa interativo…</b>Preparando os dados táticos salvos neste computador.</div>';
  try{
    const available=await Promise.race([
      window.tarkas.maps('regular'),
      new Promise((_,reject)=>setTimeout(()=>reject(new Error('timeout')),6000))
    ]);
    if(!Array.isArray(available)||!available.length)throw new Error('empty maps');
    await renderRaidScreen();
  }catch(error){
    console.error('Tarkas map screen',error);
    content.innerHTML='<div class="placeholder"><b>Não foi possível preparar os mapas agora.</b>Os demais recursos continuam disponíveis.<br><button type="button" class="qaction">Tentar novamente</button></div>';
    content.querySelector('button').onclick=()=>raid();
  }
};

async function openTarkasPage(page){
  stopMapClock();
  renderActiveProfile();
  document.querySelectorAll('#nav button').forEach(button=>button.classList.toggle('active',button.dataset.page===page));
  title.textContent=names[page];
  content.innerHTML='<div class="placeholder"><b>Carregando…</b>Preparando as informações salvas neste computador.</div>';
  try{
    if(page==='dashboard')await dashboard();
    else if(page==='quests')await quests();
    else if(page==='mapa')await raid();
    else if(page==='battlepass')await battlePass();
    else if(page==='armory')await armory();
    else if(page==='operations')await operations();
    else if(page==='hideout')await hideout();
    else if(page==='story')await story();
    else if(page==='market')await market();
    else if(page==='roadmap')await roadmap();
  }catch(error){
    console.error('Tarkas page',page,error);
    content.innerHTML='<div class="placeholder"><b>Esta área não pôde ser carregada agora.</b>Os dados locais permanecem preservados.<br><button type="button" class="qaction">Tentar novamente</button></div>';
    content.querySelector('button').onclick=()=>openTarkasPage(page);
  }finally{window.tarkasI18n?.translateUi(appLanguage,content)}
}
function renderActiveProfile(){const status=document.querySelector('aside .status');if(!status||status.dataset.profileLoading)return;status.dataset.profileLoading='true';window.tarkas.currentProfile().then(profile=>{let label=status.querySelector('.active-profile');if(!label){label=document.createElement('small');label.className='active-profile';status.append(label)}label.textContent='Perfil: '+profile.name}).catch(()=>{}).finally(()=>delete status.dataset.profileLoading)}
document.querySelectorAll('#nav button').forEach(button=>button.onclick=()=>openTarkasPage(button.dataset.page));
async function initializeLanguage(){
  const select=document.querySelector('#language-select');
  try{appLanguage=window.tarkasI18n.normalize(await window.tarkas.getSetting('language',window.tarkasI18n.detect()))}catch{appLanguage=window.tarkasI18n.detect()}
  syncLanguageChrome();
  select.onchange=async()=>{
    appLanguage=window.tarkasI18n.normalize(select.value);
    syncLanguageChrome();
    try{await window.tarkas.saveSetting('language',appLanguage)}catch{}
    await openTarkasPage(document.querySelector('#nav button.active')?.dataset.page||'dashboard');
  };
  await openTarkasPage('dashboard');
}

/* Painéis assíncronos podem nascer depois do primeiro render; traduza-os no idioma ativo. */
const liveLanguageObserver=new MutationObserver(()=>{
  if(appLanguage==='pt-BR')return;
  window.tarkasI18n?.translateUi(appLanguage,content);
});
liveLanguageObserver.observe(content,{childList:true,subtree:true});

function enhanceDashboardRaidCard(){
  const card=[...content.querySelectorAll('.card')].find(item=>item.querySelector('label')?.textContent==='Assistente de Raid');
  if(!card||card.dataset.raidShortcut)return;
  card.dataset.raidShortcut='ready';
  const button=document.createElement('button');
  button.type='button';button.className='qaction';button.textContent='Planejar raid';
  button.onclick=()=>openTarkasPage('mapa');
  card.append(button);
}
function restoreRaidPreferences(){
  const map=document.querySelector('#raidmap');
  if(!map||map.dataset.preferencesReady)return;
  map.dataset.preferencesReady='ready';
  window.tarkas.getSetting('lastRaidMap','').then(id=>{
    if(id&&[...map.options].some(option=>option.value===id)&&!map.value){map.value=id;map.dispatchEvent(new Event('change'))}
  }).catch(()=>{});
  map.addEventListener('change',()=>window.tarkas.saveSetting('lastRaidMap',map.value).catch(()=>{}));
  ['fx','fs','fb','fq','fw'].forEach(id=>{
    const filter=document.querySelector('#'+id);
    if(!filter)return;
    window.tarkas.getSetting('raidFilter:'+id,filter.checked).then(value=>{filter.checked=value!==false&&value!=='false';filter.dispatchEvent(new Event('change'))}).catch(()=>{});
    filter.addEventListener('change',()=>window.tarkas.saveSetting('raidFilter:'+id,filter.checked).catch(()=>{}));
  });
}
const raidPreferenceObserver=new MutationObserver(()=>{enhanceDashboardRaidCard();restoreRaidPreferences()});
raidPreferenceObserver.observe(content,{childList:true,subtree:true});

async function addReminderPanel(){
  const grid=content.querySelector('.grid');
  if(!grid||grid.dataset.reminderPanel)return;
  grid.dataset.reminderPanel='loading';
  try{
    const data=await window.tarkas.dashboard();
    if(grid!==content.querySelector('.grid'))return;
    const card=document.createElement('section');
    card.className='card wide reminder-panel';
    const label=document.createElement('label');label.className='reminder-title';label.innerHTML='<span>LEMBRETES DE RAID</span><small>Planeje antes de entrar</small>';
    const form=document.createElement('form');form.className='reminder-form';
    const input=document.createElement('input');input.className='reminder-input';input.required=true;input.maxLength=160;input.placeholder='O que você não pode esquecer?';input.setAttribute('aria-label','Novo lembrete');
    const due=document.createElement('input');due.className='reminder-due';due.type='datetime-local';due.title='Data e hora opcional';due.setAttribute('aria-label','Data e hora do lembrete, opcional');
    const button=document.createElement('button');button.className='qaction reminder-add';button.textContent='+ Adicionar';
    form.append(input,due,button);
    const list=document.createElement('div');list.className='reminder-list';
    if(data.reminders.length){
      data.reminders.forEach(reminder=>{
        const row=document.createElement('div');row.className='reminder-row'+(reminder.due_at&&new Date(reminder.due_at)<new Date()?' overdue':'');
        const text=document.createElement('span');text.textContent=reminder.title+(reminder.due_at?' · '+new Date(reminder.due_at).toLocaleString('pt-BR'):'');
        const done=document.createElement('button');done.type='button';done.className='qaction';done.textContent='Feito';
        done.onclick=async()=>{done.disabled=true;try{await window.tarkas.completeReminder(reminder.id);openTarkasPage('dashboard')}catch{done.disabled=false}};
        row.append(text,done);list.append(row);
      });
    }else{const empty=document.createElement('small');empty.className='reminder-empty';empty.innerHTML='<b>Sem lembretes por enquanto.</b><span>Adicione algo importante para a próxima raid.</span>';list.append(empty)}
    form.onsubmit=async event=>{event.preventDefault();button.disabled=true;try{await window.tarkas.addReminder(input.value,due.value?new Date(due.value).toISOString():'');openTarkasPage('dashboard')}catch{button.disabled=false;input.focus()}};
    card.append(label,form,list);grid.append(card);grid.dataset.reminderPanel='ready';
  }catch{grid.dataset.reminderPanel='error'}
}
const reminderPanelObserver=new MutationObserver(addReminderPanel);
reminderPanelObserver.observe(content,{childList:true,subtree:true});

async function addDataControl(){
  const card=[...content.querySelectorAll('.card')].find(item=>item.querySelector('label')?.textContent==='Assistente de Raid');
  if(!card||card.dataset.dataControl)return;
  card.dataset.dataControl='loading';
  try{
    const status=await window.tarkas.dataStatus();
    if(card!==[...content.querySelectorAll('.card')].find(item=>item.querySelector('label')?.textContent==='Assistente de Raid'))return;
    const control=document.createElement('section');control.className='data-control';
    const text=document.createElement('small');
    const updated=status.last?.updatedAt?new Date(status.last.updatedAt).toLocaleString('pt-BR'):'ainda não disponível';
    text.textContent='Dados táticos atualizados: '+updated;
    const button=document.createElement('button');button.type='button';button.className='qaction';button.textContent='Atualizar dados';
    button.onclick=async()=>{button.disabled=true;text.textContent='Atualizando dados táticos…';try{const result=await window.tarkas.syncData('regular');text.textContent=result.failed?.length?'Atualização parcial. Alguns dados continuarão no cache.':'Dados táticos atualizados agora.'}catch{text.textContent='Não foi possível atualizar agora. O cache local foi preservado.'}finally{button.disabled=false}};
    control.append(text,button);card.append(control);card.dataset.dataControl='ready';
  }catch{card.dataset.dataControl='error'}
}
const dataControlObserver=new MutationObserver(addDataControl);
dataControlObserver.observe(content,{childList:true,subtree:true});

async function addObjectiveProgress(){
  const list=document.querySelector('#realquests');
  if(!list||list.dataset.objectiveProgress)return;
  list.dataset.objectiveProgress='loading';
  try{
    const [catalog,progress]=await Promise.all([window.tarkas.questCatalog('regular'),window.tarkas.progress()]);
    if(list!==document.querySelector('#realquests'))return;
    const completed=new Set(progress.objectives.filter(item=>item.done).map(item=>item.id));
    const byId=new Map(catalog.quests.map(quest=>[quest.id,quest]));
    list.querySelectorAll('.qrow').forEach(row=>{
      const action=row.querySelector('.qaction[data-id]');
      if(!action||action.dataset.status!=='completed'||row.querySelector('.objective-progress'))return;
      const quest=byId.get(action.dataset.id);if(!quest?.objectives?.length)return;
      const section=document.createElement('section');section.className='objective-progress';
      const heading=document.createElement('b');heading.textContent='Progresso dos objetivos';section.append(heading);
      quest.objectives.forEach(objective=>{
        const label=document.createElement('label');
        const check=document.createElement('input');check.type='checkbox';check.checked=completed.has(objective.id);
        const text=document.createElement('span');text.textContent=objective.description+(objective.count>1?' ×'+objective.count:'');
        check.onchange=async()=>{check.disabled=true;try{const state=await window.tarkas.toggleObjective(objective.id,quest.id);check.checked=Boolean(state.done)}catch{check.checked=!check.checked}finally{check.disabled=false}};
        label.append(check,text);section.append(label);
      });
      row.querySelector('.qguide')?.append(section);
    });
    list.dataset.objectiveProgress='ready';
  }catch{list.dataset.objectiveProgress='error'}
}
const objectiveProgressObserver=new MutationObserver(addObjectiveProgress);
objectiveProgressObserver.observe(content,{childList:true,subtree:true});

function addRaidNotes(){
  const out=document.querySelector('#raidout');
  const briefing=out?.querySelector('.raid-briefing');
  const mapName=document.querySelector('#mapstage .maphead b')?.textContent;
  if(!out||!briefing||!mapName||out.querySelector('.raid-notes'))return;
  const notes=document.createElement('section');notes.className='raid-notes card';
  const label=document.createElement('label');label.textContent='Notas desta rota';
  const area=document.createElement('textarea');area.maxLength=600;area.rows=3;area.placeholder='Ex.: entrar pelo lado leste, verificar a sala 214 e sair pela ZB-1011.';
  const action=document.createElement('div');
  const button=document.createElement('button');button.type='button';button.className='qaction';button.textContent='Salvar nota';
  const status=document.createElement('small');status.className='muted';
  button.onclick=async()=>{button.disabled=true;try{await window.tarkas.saveSetting('raidNote:'+mapName,area.value.trim());status.textContent='Nota salva para '+mapName+'.'}catch{status.textContent='Não foi possível salvar a nota.'}finally{button.disabled=false}};
  action.append(button,status);notes.append(label,area,action);out.insertBefore(notes,briefing.nextSibling);
  window.tarkas.getSetting('raidNote:'+mapName,'').then(value=>{area.value=value||''}).catch(()=>{});
}
const raidNotesObserver=new MutationObserver(addRaidNotes);
raidNotesObserver.observe(content,{childList:true,subtree:true});

