async function addNextAction(){const grid=content.querySelector('.grid');if(!grid||grid.dataset.nextAction)return;grid.dataset.nextAction='loading';try{const level=await window.tarkas.playerLevel(),quests=await window.tarkas.plannedQuests('regular',level);if(grid!==content.querySelector('.grid'))return;const quest=quests.find(item=>item.status==='active')||quests.find(item=>item.status==='available');const card=document.createElement('section');card.className='card wide next-action';const label=document.createElement('label');label.textContent='Próxima melhor ação';const title=document.createElement('h2');const note=document.createElement('p');const button=document.createElement('button');button.className='qaction';if(quest){title.textContent=quest.name;note.textContent=quest.trader+' · '+quest.map+' · '+(quest.status==='active'?'em andamento':'disponível');button.textContent='Abrir plano de raid';button.onclick=()=>{pendingMapName=quest.map;pendingQuestId=quest.id;openTarkasPage('mapa')}}else{title.textContent='Sem quest pronta agora';note.textContent='Aumente seu nível ou conclua os pré-requisitos para liberar a próxima tarefa.';button.textContent='Ver quests';button.onclick=()=>openTarkasPage('quests')}card.append(label,title,note,button);grid.append(card);grid.dataset.nextAction='ready'}catch{grid.dataset.nextAction='error'}}
const nextActionObserver=new MutationObserver(addNextAction);nextActionObserver.observe(content,{childList:true,subtree:true});
