names.armory='Arsenal';
async function armory(){
  content.innerHTML='<div class="placeholder"><b>Abrindo arsenal…</b>Indexando armas e acessórios salvos localmente.</div>';
  const items=await window.tarkas.armoryCatalog('regular');
  window.__tarkasArmoryItems=items;
  content.innerHTML='<section class="armory-head"><div><small>CATÁLOGO LOCAL</small><h2>Arsenal</h2><p><b>'+items.filter(item=>item.kind==='weapon').length+'</b> armas · <b>'+items.filter(item=>item.kind==='attachment').length+'</b> acessórios</p></div><div class="armory-controls"><input id="armory-search" placeholder="Buscar arma, mod ou calibre"><select id="armory-kind"><option value="all">Tudo</option><option value="weapon">Armas</option><option value="attachment">Acessórios</option></select></div></section><div id="armory-list" class="armory-list"></div>';
  const draw=()=>{const term=document.querySelector('#armory-search').value.trim().toLowerCase(),kind=document.querySelector('#armory-kind').value;const rows=items.filter(item=>(kind==='all'||item.kind===kind)&&(!term||[item.name,item.shortName,item.caliber,...item.types].join(' ').toLowerCase().includes(term))).slice(0,180);const list=document.querySelector('#armory-list');list.replaceChildren(...rows.map(item=>{const row=document.createElement('article');row.className='armory-item';const image=document.createElement('img');image.src=item.icon;image.alt='';image.loading='lazy';const info=document.createElement('div');const type=document.createElement('span');type.className='tag';type.textContent=item.kind==='weapon'?'ARMA':'ACESSÓRIO';const name=document.createElement('h3');name.textContent=item.name;const meta=document.createElement('small');meta.textContent=[item.caliber,item.ergonomics!==null?'Erg. '+item.ergonomics:'',item.recoil!==null?'Rec. '+item.recoil:''].filter(Boolean).join(' · ')||item.types.slice(0,3).join(' · ');info.append(type,name,meta);const price=document.createElement('div');price.className='armory-price';price.textContent=item.price?item.price.toLocaleString('pt-BR')+' ₽':'—';row.append(image,info,price);return row}));if(!rows.length)list.innerHTML='<div class="placeholder">Nenhum item encontrado.</div>'};document.querySelector('#armory-search').oninput=draw;document.querySelector('#armory-kind').onchange=draw;draw();
}
