names.operations='Operações';
async function operations(){
  content.innerHTML='<div class="placeholder"><b>Preparando central operacional…</b></div>';
  const [summary,current,profiles]=await Promise.all([window.tarkas.commandOverview(),window.tarkas.currentProfile(),window.tarkas.profiles()]);
  const modules=[['Builds salvas',summary.builds,'Monte e guarde configurações de armas.'],['Stash e compras',summary.stash,'Inventário, itens reservados e lista de compra.'],['Pings de mapa',summary.pins,'Rotas e pontos pessoais por mapa.'],['Histórico de raids',summary.raids,'Extrações, loot, eliminações e anotações.'],['Metas em aberto',summary.goals,'Wipe, traders, Kappa e metas pessoais.'],['Favoritos',summary.favorites,'Armas, munições, chaves e itens marcados.']];
  content.innerHTML='<section class="operations-hero"><small>PAINEL EM EXPANSÃO</small><h2>Central de Operações</h2><p>Seu progresso, equipamentos e planejamento em um único lugar.</p></section><section class="profile-switcher"><div><small>PERFIL ATIVO</small><h3></h3><p></p></div><div class="profile-controls"><select aria-label="Selecionar perfil">'+profiles.map(profile=>'<option value="'+profile.id+'"'+(profile.active?' selected':'')+'>'+profile.name+'</option>').join('')+'</select><button type="button" class="qaction">Novo perfil</button></div><small class="profile-status"></small></section><div class="operations-grid">'+modules.map(([name,count,description])=>'<article><span>'+name+'</span><b>'+count+'</b><p>'+description+'</p><small>Em preparação</small></article>').join('')+'</div><section class="operations-roadmap"><b>Próximos módulos do pacote</b><p>Montador de armas · builds salvas · lista de compras · hideout · Kappa tracker · histórico de raids · pings pessoais · relatórios e modo equipe.</p></section>';
  const profilePanel=content.querySelector('.profile-switcher'),select=profilePanel.querySelector('select'),newProfile=profilePanel.querySelector('button'),status=profilePanel.querySelector('.profile-status');profilePanel.querySelector('h3').textContent=current.name;profilePanel.querySelector('p').textContent='Nível '+current.level+' · '+current.builds+' builds · '+current.stash+' itens no stash · '+current.raids+' raids';select.onchange=async()=>{select.disabled=true;try{await window.tarkas.switchProfile(select.value);await openTarkasPage('operations')}catch{status.textContent='Não foi possível trocar o perfil.';select.disabled=false}};newProfile.onclick=async()=>{const name=prompt('Nome do novo perfil:');if(name===null)return;newProfile.disabled=true;try{await window.tarkas.createProfile(name);await openTarkasPage('operations')}catch(error){status.textContent=error?.message||'Não foi possível criar o perfil.';newProfile.disabled=false}};
}
