async function addProgressHub(){
  const anchor=document.querySelector('.operations-roadmap');
  if(!anchor||document.querySelector('.progress-hub'))return;
  const hub=document.createElement('section');hub.className='progress-hub';hub.innerHTML='<header><div><small>ETAPA 0.7 · PROGRESSO E KAPPA</small><h3>Central de progresso</h3><p>Use estes atalhos para transformar objetivos soltos em um plano de evolução do PMC.</p></div></header><div class="progress-hub-cards"><article><small>KAPPA</small><b>—</b><span>quests obrigatórias concluídas</span><button type="button">Abrir Kappa Tracker</button></article><article><small>THE COLLECTOR</small><b>—</b><span>itens necessários registrados</span><button type="button">Ver itens da missão</button></article><article><small>HIDEOUT</small><b>—</b><span>níveis registrados</span><button type="button">Planejar upgrades</button></article><article><small>METAS</small><b>↗</b><span>metas pessoais, wipe e traders</span><button type="button">Abrir metas</button></article></div>';
  anchor.insertAdjacentElement('afterend',hub);
  const cards=[...hub.querySelectorAll('.progress-hub-cards article')];
  cards[0].querySelector('button').onclick=()=>document.querySelector('.kappa-panel')?.scrollIntoView({behavior:'smooth',block:'start'});
  cards[1].querySelector('button').onclick=()=>{const collector=document.querySelector('.kappa-collector');if(collector)collector.scrollIntoView({behavior:'smooth',block:'start'});else cards[0].querySelector('button').click()};
  cards[2].querySelector('button').onclick=()=>openTarkasPage('hideout');
  cards[3].querySelector('button').onclick=()=>document.querySelector('.goals-panel')?.scrollIntoView({behavior:'smooth',block:'start'});
  try{
    const [kappa,stations,rawLevels]=await Promise.all([window.tarkas.kappaTracker('regular'),window.tarkas.hideoutCatalog('regular'),window.tarkas.getSetting('hideoutLevels','{}')]);
    if(hub!==document.querySelector('.progress-hub'))return;
    let levels={};try{levels=JSON.parse(rawLevels)||{}}catch{}
    const totalLevels=stations.reduce((sum,station)=>sum+station.levels.length,0);
    const completeLevels=stations.reduce((sum,station)=>sum+Math.min(Number(levels[station.id])||0,station.levels.length),0);
    cards[0].querySelector('b').textContent=kappa.completed+'/'+kappa.total;
    cards[1].querySelector('b').textContent=kappa.collector?.items?.length||0;
    cards[2].querySelector('b').textContent=completeLevels+'/'+totalLevels;
  }catch{hub.remove()}
}
const progressHubObserver=new MutationObserver(()=>addProgressHub().catch(()=>{}));progressHubObserver.observe(content,{childList:true,subtree:true});
