async function enhanceKappaTracker(){
  const panels=[...document.querySelectorAll('.kappa-panel')];if(!panels.length)return;panels.slice(1).forEach(panel=>panel.remove());const panel=panels[0];if(panel.dataset.interactiveKappa)return;panel.dataset.interactiveKappa='loading';
  try{const kappa=await window.tarkas.kappaTracker('regular');if(panel!==document.querySelector('.kappa-panel'))return;panel.replaceChildren();const heading=document.createElement('h3');heading.innerHTML='Kappa tracker <b>'+kappa.completed+'/'+kappa.total+'</b>';const intro=document.createElement('small');intro.className='kappa-intro';intro.textContent='Clique em uma missão para abrir o guia completo e acompanhar o progresso.';const list=document.createElement('div');list.className='kappa-quest-list';kappa.quests.forEach(quest=>{const row=document.createElement('button');row.type='button';row.className='kappa-quest '+(quest.status==='completed'?'done':'');row.innerHTML='<span></span><b></b><small></small>';row.querySelector('span').textContent=quest.status==='completed'?'✓':'○';row.querySelector('b').textContent=quest.name;row.querySelector('small').textContent=quest.trader+' · '+quest.map;row.onclick=async()=>{await openTarkasPage('quests');const search=document.querySelector('#qs'),state=document.querySelector('#qstate');if(state){state.value='all';state.dispatchEvent(new Event('change'))}if(search){search.value=quest.name;search.dispatchEvent(new Event('input'));search.scrollIntoView({behavior:'smooth',block:'center'})}};list.append(row)});panel.append(heading,intro,list);
    if(kappa.collector){const collector=document.createElement('section');collector.className='kappa-collector';collector.innerHTML='<b>THE COLLECTOR · ITENS NECESSÁRIOS</b><small>Itens exigidos pela missão final do Kappa conforme os dados locais.</small><div></div>';const items=collector.querySelector('div');if(kappa.collector.items.length)kappa.collector.items.forEach(item=>{const row=document.createElement('span');if(item.icon){const image=document.createElement('img');image.src=item.icon;image.alt='';image.loading='lazy';row.append(image)}row.append(document.createTextNode(item.name));items.append(row)});else items.innerHTML='<em>Os itens ainda não foram fornecidos estruturadamente pela fonte local. Atualize os dados para carregar a lista.</em>';panel.append(collector)}
    panel.dataset.interactiveKappa='ready';
  }catch{panel.dataset.interactiveKappa='error'}
}
