function bindFullArmoryDetails(){document.querySelectorAll('.armory-item[data-details]:not([data-full-details])').forEach(row=>{const basic=window.__tarkasArmoryItems?.find(entry=>entry.name===row.querySelector('h3')?.textContent);if(!basic)return;row.dataset.fullDetails='ready';const open=async()=>{let panel=document.querySelector('#armory-details');if(!panel){panel=document.createElement('section');panel.id='armory-details';panel.className='armory-full-details';document.querySelector('.armory-head')?.insertAdjacentElement('afterend',panel)}panel.innerHTML='<div class="placeholder">Carregando ficha técnica…</div>';try{const item=await window.tarkas.armoryDetail('regular',basic.id);if(!item)throw new Error('missing');panel.replaceChildren();const top=document.createElement('header');const image=document.createElement('img');image.src=item.icon;image.alt='';const intro=document.createElement('div');const tag=document.createElement('span');tag.className='tag';tag.textContent=item.types.includes('gun')?'ARMA':'ACESSÓRIO';const title=document.createElement('h2');title.textContent=item.name;const story=document.createElement('p');story.textContent=item.description||'Sem descrição disponível no cache local.';intro.append(tag,title,story);const close=document.createElement('button');close.type='button';close.className='qaction';close.textContent='Fechar';close.onclick=()=>panel.remove();top.append(image,intro,close);const stats=document.createElement('div');stats.className='armory-stats';[['Calibre',item.caliber],['Ergonomia',item.ergonomics],['Recuo vertical',item.recoilVertical],['Recuo horizontal',item.recoilHorizontal],['Cadência',item.fireRate?item.fireRate+' rpm':'' ],['Alcance',item.effectiveDistance?item.effectiveDistance+' m':''],['Preço',item.price?item.price.toLocaleString('pt-BR')+' ₽':'']].filter(([,value])=>value!==null&&value!==undefined&&value!=='').forEach(([label,value])=>{const stat=document.createElement('div');stat.innerHTML='<small>'+label+'</small><b>'+value+'</b>';stats.append(stat)});panel.append(top,stats,renderArmoryCollection('Munições compatíveis',item.allowedAmmo),renderArmoryCollection('Acessórios instalados',item.installed));item.slots.filter(slot=>slot.items.length).slice(0,12).forEach(slot=>panel.append(renderArmoryCollection('Slot: '+slot.name+(slot.required?' · obrigatório':''),slot.items)));panel.scrollIntoView({behavior:'smooth',block:'start'})}catch{panel.innerHTML='<div class="placeholder"><b>Não foi possível abrir esta ficha.</b>O restante do Arsenal continua disponível.</div>'}};row.onclick=open;row.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open()}}})}
