  svg.addEventListener('click',async event=>{if(svg.dataset.pinPlacement!=='ready')return;event.preventDefault();event.stopPropagation();const rect=svg.getBoundingClientRect(),box=(svg.getAttribute('viewBox')||'0 0 100 100').trim().split(/\s+/).map(Number);if(rect.width<=0||rect.height<=0||box.length!==4)return;const x=box[0]+(event.clientX-rect.left)/rect.width*box[2],z=box[1]+(event.clientY-rect.top)/rect.height*box[3],[label,note]=form.elements;try{await window.tarkas.addMapPin(mapName,label.value,note.value,x,z);label.value='';note.value='';svg.dataset.pinPlacement='';form.querySelector('.place-map-pin').textContent='Posicionar no mapa';await render()}catch{form.querySelector('.place-map-pin').textContent='Tentar posicionar'}});
