async function addTarkasAcademy(){
  if(document.querySelector('#nav button.active')?.dataset.page!=='story'||document.querySelector('.tarkas-academy'))return;
  const hero=content.querySelector('.story-hero');if(!hero)return;
  let saved={};try{saved=JSON.parse(await window.tarkas.getSetting('academyProgress','{}'))||{}}catch{}
  if(document.querySelector('#nav button.active')?.dataset.page!=='story'||document.querySelector('.tarkas-academy'))return;
  const lessons=[
    ['primeira-raid','Primeira raid segura','Escolha o mapa, confira o tempo, defina uma extração e entre com um objetivo simples.'],
    ['navegacao','Como ler o mapa','Use filtros: deixe visível somente o que procura — documentos, stash, chaves ou o objetivo da missão.'],
    ['loadout','Loadout essencial','Separe arma, munição compatível, cura, água e uma rota de saída antes de clicar em “Pronto”.'],
    ['progresso','Progresso sem desperdício','Use Quests, História, Kappa e Hideout como planos separados; não tente concluir tudo na mesma raid.'],
    ['economia','Economia consciente','Compare comerciante e mercado. Uma cotação é referência; confirme disponibilidade e desbloqueios antes de comprar.']
  ];
  const panel=document.createElement('section');panel.className='tarkas-academy';panel.innerHTML='<header><div><small>ACADEMIA TARKAS · PARA NOVOS PMCs</small><h3>Comece sabendo o que fazer</h3><p>Um roteiro curto, prático e salvo no seu perfil. Marque apenas o que você já entendeu ou praticou.</p></div><button type="button" class="qaction">Abrir mapa para treino</button></header><div class="academy-lessons"></div>';
  const list=panel.querySelector('.academy-lessons');const render=()=>{list.replaceChildren();lessons.forEach(([id,title,copy],index)=>{const item=document.createElement('label'),check=document.createElement('input'),body=document.createElement('span');check.type='checkbox';check.checked=Boolean(saved[id]);check.onchange=()=>{saved[id]=check.checked;window.tarkas.saveSetting('academyProgress',JSON.stringify(saved)).catch(()=>{})};body.innerHTML='<b>'+String(index+1).padStart(2,'0')+' · '+title+'</b><small>'+copy+'</small>';item.append(check,body);list.append(item)})};render();panel.querySelector('button').onclick=()=>openTarkasPage('mapa');hero.insertAdjacentElement('afterend',panel);
}
const tarkasAcademyObserver=new MutationObserver(()=>addTarkasAcademy().catch(()=>{}));tarkasAcademyObserver.observe(content,{childList:true,subtree:true});
