async function addDataHealth(){const active=document.querySelector('#nav button.active')?.dataset.page;if(active!=='dashboard'||document.querySelector('.data-health')||content.dataset.dataHealthLoading)return;content.dataset.dataHealthLoading='true';try{const status=await window.tarkas.dataStatus();if(document.querySelector('#nav button.active')?.dataset.page!=='dashboard'||document.querySelector('.data-health'))return;const panel=document.createElement('section');panel.className='data-health';const when=status.last?.updatedAt?new Date(status.last.updatedAt):null;const age=when?Math.max(0,Math.round((Date.now()-when)/3600000)):null;panel.innerHTML='<div><small>BASE DE DADOS</small><b></b><span></span></div><button class="qaction">Atualizar agora</button>';panel.querySelector('b').textContent=when?'Última atualização: '+when.toLocaleString('pt-BR'):'Dados ainda não sincronizados';panel.querySelector('span').textContent=age===null?'Sincronize para carregar quests, mapas e preços.':age<6?'Dados recentes.':'Dados com '+age+'h — atualize para consultar novidades.';const button=panel.querySelector('button');button.onclick=async()=>{button.disabled=true;button.textContent='Atualizando…';try{await window.tarkas.syncData('regular');button.textContent='Concluído';setTimeout(()=>openTarkasPage('dashboard'),600)}catch{button.disabled=false;button.textContent='Tentar novamente'}};content.prepend(panel)}finally{delete content.dataset.dataHealthLoading}}
