  try{const items=await window.tarkas.marketCatalog('regular');if(stage!==document.querySelector('#mapstage')||out.querySelector('.map-access-directory'))return;const expression=/(cart[aã]o de acesso à terragroup labs|cart[aã]o de acesso (amarelo|azul|preto|verde|vermelho|violeta)|cart[aã]o-chave de unidade residencial)/i;const cards=items.filter(item=>item.types?.includes('keys')&&expression.test(item.name));const panel=document.createElement('section');panel.className='map-access-directory';panel.innerHTML='<header><small>ACESSOS DO MAPA</small><h3>Cartões-chave de The Lab</h3><p>Lista completa dos cartões de acesso encontrados no catálogo local. Clique para abrir o preço e as fontes de compra.</p></header><div></div>';const list=panel.querySelector('div');cards.forEach(card=>{const button=document.createElement('button');button.type='button';button.innerHTML=(card.icon?'<img src="'+card.icon+'" alt="">':'')+'<span><b></b><small></small></span>';button.querySelector('b').textContent=card.name;button.querySelector('small').textContent=card.price?'Mercado: '+card.price.toLocaleString('pt-BR')+' ₽':'Sem cotação local';button.onclick=async()=>{await openTarkasPage('market');setTimeout(()=>{const search=document.querySelector('.market-controls input');if(search){search.value=card.name;search.dispatchEvent(new Event('input'))}},100)};list.append(button)});if(!cards.length)list.innerHTML='<small>Os cartões de The Lab ainda não foram carregados na base local. Atualize os dados e tente novamente.</small>';out.querySelector('.raid-planning-surface,.raid-summary')?.insertAdjacentElement('beforebegin',panel)}catch{}finally{delete out.dataset.mapAccessLoading}
