function labelDocumentMapMarkers(){
  const stage=document.querySelector('#mapstage');if(!stage||stage.dataset.specialFilter!=='documents')return;const svg=stage.querySelector('.overlaymap');if(!svg)return;const marks=[...svg.querySelectorAll('.mark.document')],signature=marks.map(mark=>mark.querySelector('title')?.textContent||'Documento').join('|');if(stage.dataset.documentLabelSignature===signature)return;stage.dataset.documentLabelSignature=signature;svg.querySelectorAll('.document-map-label').forEach(node=>node.remove());
  marks.forEach((mark,index)=>{const shape=mark.querySelector('.marker-shape,[cx]');if(!shape)return;let x=Number(shape.getAttribute('cx')),y=Number(shape.getAttribute('cy'));if(!Number.isFinite(x)||!Number.isFinite(y)){const rect=mark.querySelector('rect');if(rect){x=Number(rect.getAttribute('x'))+Number(rect.getAttribute('width'))/2;y=Number(rect.getAttribute('y'))+Number(rect.getAttribute('height'))/2}}if(!Number.isFinite(x)||!Number.isFinite(y))return;const title=(mark.querySelector('title')?.textContent||'Documento').split(' · ')[0].slice(0,34),label=document.createElementNS('http://www.w3.org/2000/svg','text');label.setAttribute('class','document-map-label');label.setAttribute('x',x+5);label.setAttribute('y',y-5);label.textContent='DOC '+String(index+1)+' · '+title;svg.append(label)})
}
