  const labels=['Nível do personagem planejado','Quests exigidas revisadas','Hideout necessário conferido','História principal revisada','Itens e dinheiro separados','Skills e maestria avaliadas'];labels.forEach((label,index)=>{const row=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=Boolean(steps[index]);const text=document.createElement('span');text.textContent=label;check.onchange=()=>{steps[index]=check.checked;window.tarkas.saveSetting('patch120PrestigeSteps',JSON.stringify(steps)).catch(()=>{})};row.append(check,text);stepList.append(row)});
  const [sync,customs,interchange]=panel.querySelectorAll('footer button'),status=panel.querySelector('footer small');
